class RadioCiwaraApp extends StatelessWidget{const RadioCiwaraApp({super.key});@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Radio Ciwara 105.5 FM',theme:ThemeData(useMaterial3:true,brightness:Brightness.dark,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFFD4145A),brightness:Brightness.dark)),home:const AppShell());}
